import json, urllib.request

def player(vid, context, ua="Mozilla/5.0"):
    key = "AIzaSyAO_FJ2SlqU8Q4STEHLGCilw_Y9_11qwWk"
    url = f"https://www.youtube.com/youtubei/v1/player?key={key}&prettyPrint=false"
    body = json.dumps({"context": context, "videoId": vid, "contentCheckOk": True, "racyCheckOk": True}).encode()
    req = urllib.request.Request(url, data=body, headers={"Content-Type": "application/json", "User-Agent": ua})
    return json.load(urllib.request.urlopen(req, timeout=30))

clients = {
 "IOS": ({"client": {"clientName": "IOS", "clientVersion": "19.29.1", "deviceModel": "iPhone16,2", "osName": "iPhone OS", "osVersion": "17.5.1.21F90", "hl": "en", "timeZone": "America/New_York"}}, "com.google.ios.youtube/19.29.1 (iPhone14,3; U; CPU iOS 15_0 like Mac OS X)"),
 "TVHTML5_SIMPLY": ({"client": {"clientName": "TVHTML5_SIMPLY_EMBEDDED_PLAYER", "clientVersion": "2.0", "hl": "en"}}, "Mozilla/5.0"),
 "WEB_EMBEDDED": ({"client": {"clientName": "WEB_EMBEDDED_PLAYER", "clientVersion": "1.20240613.01.00", "hl": "en"}}, "Mozilla/5.0"),
 "MWEB": ({"client": {"clientName": "MWEB", "clientVersion": "2.20240613.01.00", "hl": "en"}}, "Mozilla/5.0 (iPhone; CPU iPhone OS 16_7_10 like Mac OS X)"),
}
for name, (ctx, ua) in clients.items():
    try:
        j = player("60ItHLz5YJA", ctx, ua)
        st = j.get("playabilityStatus", {}).get("status")
        vd = j.get("videoDetails", {})
        sb = j.get("storyboards", {})
        print(name, "|", st, "|", vd.get("title"), "|", vd.get("lengthSeconds"))
        print("   sb:", json.dumps(sb)[:300])
    except Exception as e:
        print(name, "ERR", e)
EOF"}

