import json, os, time, urllib.request, io
from PIL import Image
import numpy as np

meta = json.load(open("sb/meta.json"))
UA = {"User-Agent": "Mozilla/5.0"}
def get(u, tries=4):
    for i in range(tries):
        try:
            return urllib.request.urlopen(urllib.request.Request(u, headers=UA), timeout=25).read()
        except Exception as e:
            if i == tries-1: raise
            time.sleep(2)

out = {}
for k, m in meta.items():
    sb = m["sb"]; vid = m["vid"]
    tmpl = sb["templateUrl"]; gw, gh = sb["storyboardWidth"], sb["storyboardHeight"]
    cw, ch = sb["width"], sb["height"]; count = sb["count"]
    nsprites = sb["storyboardCount"]
    frames = []
    for s in range(nsprites):
        url = tmpl.replace("$M", str(s)) if "$M" in tmpl else tmpl
        try:
            data = get(url)
        except Exception as e:
            print(k, s, "sprite ERR", str(e)[:80]); continue
        img = Image.open(io.BytesIO(data)).convert("RGB")
        W, H = img.size
        a = np.asarray(img).astype(np.float32)
        for cell in range(gw*gh):
            idx = s*gw*gh + cell
            if idx >= count: break
            cx, cy = cell % gw, cell // gw
            block = a[cy*ch:(cy+1)*ch, cx*cw:(cx+1)*cw]
            # trim any letterbox rows (top/bottom near-black uniform) within cell
            rs = block.mean(axis=(1,2))
            core = block[rs > 8] if (rs < 8).sum() < ch*0.35 else block
            frames.append({"t": idx*sb["interval"]/1000.0, "rgb": core.mean(axis=(0,1)).tolist()})
    out[k] = {"name": m["name"], "vid": vid, "interval": sb["interval"], "frames": frames}
    print(k, m["name"], "frames:", len(frames))
    time.sleep(0.3)
json.dump(out, open("sb/frames.json", "w"))
print("saved sb/frames.json")
EOF"}
